('idx_model_operation_log_model_time',3,'id',1,'D');
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.statistics a LEFT JOIN compact_model_operation_indexes e ON BINARY e.index_name=BINARY a.index_name AND e.index_position=a.seq_in_index WHERE a.table_schema='__SOURCE_SCHEMA__' AND a.table_name='model_operation_log' AND e.column_name IS NULL;
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=0,1,0) FROM compact_model_operation_indexes e LEFT JOIN information_schema.statistics a ON a.table_schema='__SOURCE_SCHEMA__' AND a.table_name='model_operation_log' AND BINARY a.index_name=BINARY e.index_name AND a.seq_in_index=e.index_position WHERE a.index_name IS NULL OR NOT(BINARY a.column_name<=>BINARY e.column_name) OR a.non_unique<>e.non_unique OR a.sub_part IS NOT NULL OR a.expression IS NOT NULL OR a.index_type<>'BTREE' OR a.is_visible<>'YES' OR NOT(BINARY a.collation<=>BINARY e.direction);
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.triggers WHERE event_object_schema='__SOURCE_SCHEMA__' AND event_object_table='model_operation_log';
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=0,1,0) FROM information_schema.table_constraints WHERE table_schema='__SOURCE_SCHEMA__' AND table_name='model_operation_log' AND constraint_type='CHECK';
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=1,1,0) FROM information_schema.referential_constraints WHERE constraint_schema='__SOURCE_SCHEMA__' AND table_name='model_operation_log';
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=1,1,0) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name AND r.table_name=k.table_name WHERE k.table_schema='__SOURCE_SCHEMA__' AND k.table_name='model_operation_log' AND k.constraint_name='fk_model_operation_log_model' AND k.column_name='model_id' AND k.ordinal_position=1 AND k.position_in_unique_constraint=1 AND k.referenced_table_schema='__SOURCE_SCHEMA__' AND k.referenced_table_name='model_management' AND k.referenced_column_name='model_id' AND r.update_rule='CASCADE' AND r.delete_rule='CASCADE';
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=1,1,0) FROM information_schema.key_column_usage WHERE table_schema='__SOURCE_SCHEMA__' AND table_name='model_operation_log' AND referenced_table_name IS NOT NULL;
INSERT INTO compact_model_operation_guard SELECT NOT EXISTS(SELECT 1 FROM `__SOURCE_SCHEMA__`.model_operation_log s LEFT JOIN `__SOURCE_SCHEMA__`.model_management p ON p.model_id=s.model_id LEFT JOIN model_management t ON t.model_id=s.model_id WHERE p.model_id IS NULL OR t.model_id IS NULL OR CONVERT_TZ(s.operation_time,@compact_validation_wall_offset,'+00:00') IS NULL OR NOT(TIMESTAMPDIFF(SECOND,CONVERT_TZ(s.operation_time,@compact_validation_wall_offset,'+00:00'),s.operation_time)<=>(IF(LEFT(@compact_validation_wall_offset,1)='-',-1,1)*(CAST(SUBSTRING(@compact_validation_wall_offset,2,2) AS SIGNED)*3600+CAST(SUBSTRING(@compact_validation_wall_offset,5,2) AS SIGNED)*60))));
INSERT INTO compact_model_operation_guard SELECT IF(NOT @compact_source_clock_unresolved OR REGEXP_LIKE('__SOURCE_SNAPSHOT_SHA256__','^[a-f0-9]{64}$','c'),1,0);
INSERT INTO compact_model_operation_guard SELECT NOT EXISTS(SELECT 1 FROM audit_event WHERE kind='DETECTION_MODEL_OPERATION' OR legacy_source='model_operation_log');
INSERT INTO audit_event(event_id,kind,resource_type,detection_model_id,action,occurred_at,payload_version,payload_json,legacy_source,legacy_key,legacy_clock_json) SELECT CONCAT('legacy-model-operation-',s.id),'DETECTION_MODEL_OPERATION','DETECTION_MODEL',s.model_id,s.operation_type,IF(@compact_source_clock_unresolved,NULL,CONVERT_TZ(s.operation_time,@compact_validation_wall_offset,'+00:00')),1,JSON_OBJECT('operatorName',s.operator,'remark',s.remark,'legacyOperationTime',DATE_FORMAT(s.operation_time,'%Y-%m-%dT%H:%i:%s')),'model_operation_log',CAST(s.id AS CHAR),IF(@compact_source_clock_unresolved,JSON_OBJECT('protocol','doorhandle-legacy-clock-v1','status','UNRESOLVED','sourceTable','model_operation_log','sourceKey',JSON_OBJECT('id',s.`id`),'sourceSnapshotSha256','__SOURCE_SNAPSHOT_SHA256__','sourceRowSha256',SHA2(CAST(JSON_OBJECT('id',s.`id`,'model_id',s.`model_id`,'operation_type',s.`operation_type`,'operator',s.`operator`,'operation_time',CAST(s.`operation_time` AS CHAR CHARACTER SET utf8mb4),'remark',s.`remark`) AS CHAR CHARACTER SET utf8mb4),256),'sourceWallTimes',JSON_OBJECT('operation_time',CAST(s.`operation_time` AS CHAR))),NULL) FROM `__SOURCE_SCHEMA__`.model_operation_log s ORDER BY s.id;
INSERT INTO compact_model_operation_guard SELECT (SELECT COUNT(*) FROM `__SOURCE_SCHEMA__`.model_operation_log)=(SELECT COUNT(*) FROM audit_event WHERE kind='DETECTION_MODEL_OPERATION');
INSERT INTO compact_model_operation_guard SELECT NOT EXISTS(SELECT 1 FROM `__SOURCE_SCHEMA__`.model_operation_log s LEFT JOIN audit_event a ON BINARY a.legacy_source=BINARY 'model_operation_log' AND BINARY a.legacy_key=BINARY CAST(s.id AS CHAR)
INSERT INTO compact_model_operation_guard SELECT IF(COUNT(*)=0,1,0) FROM `__SOURCE_SCHEMA__`.model_operation_log s LEFT JOIN audit_event clock_target ON BINARY clock_target.`legacy_source`<=>BINARY 'model_operation_log' AND BINARY clock_target.`legacy_key`<=>BINARY CAST(s.id AS CHAR) WHERE (clock_target.id IS NULL OR NOT(clock_target.legacy_clock_json<=>IF(@compact_source_clock_unresolved,JSON_OBJECT('protocol','doorhandle-legacy-clock-v1','status','UNRESOLVED','sourceTable','model_operation_log','sourceKey',JSON_OBJECT('id',s.`id`),'sourceSnapshotSha256','__SOURCE_SNAPSHOT_SHA256__','sourceRowSha256',SHA2(CAST(JSON_OBJECT('id',s.`id`,'model_id',s.`model_id`,'operation_type',s.`operation_type`,'operator',s.`operator`,'operation_time',CAST(s.`operation_time` AS CHAR CHARACTER SET utf8mb4),'remark',s.`remark`) AS CHAR CHARACTER SET utf8mb4),256),'sourceWallTimes',JSON_OBJECT('operation_time',CAST(s.`operation_time` AS CHAR))),NULL)) OR NOT(clock_target.`occurred_at`<=>IF(@compact_source_clock_unresolved,NULL,CONVERT_TZ(s.operation_time,@compact_validation_wall_offset,'+00:00'))) OR NOT(BINARY clock_target.`payload_json`<=>BINARY JSON_OBJECT('operatorName',s.operator,'remark',s.remark,'legacyOperationTime',DATE_FORMAT(s.operation_time,'%Y-%m-%dT%H:%i:%s'))));
